+  const pitch = clamp(s.pitch + 0.5 * c.pitch * dt, -0.35, 0.45);
+  const targetRoll = 0.6 * c.bank;
+  const rollDelta = clamp(targetRoll - s.roll, -2 * dt, 2 * dt);
